#define main legacy_main
#include "../slit-cuda/main.cu"
#undef main
#include <vector>
#include <complex>
#include <string>
#include <algorithm>
#include <dlfcn.h>
using Z=std::complex<double>;
std::vector<Z>dft(const std::vector<Z>&a,int N){std::vector<Z>tw(N*N),tmp(N*N),out(N*N);for(int k=0;k<N;k++)for(int j=0;j<N;j++)tw[k*N+j]=std::polar(1.0,-2*M_PI*k*j/N);for(int y=0;y<N;y++)for(int k=0;k<N;k++)for(int x=0;x<N;x++)tmp[y*N+k]+=a[y*N+x]*tw[k*N+x];for(int kx=0;kx<N;kx++)for(int ky=0;ky<N;ky++)for(int y=0;y<N;y++)out[ky*N+kx]+=tmp[y*N+kx]*tw[ky*N+y];return out;}
int main(int argc,char**argv){const int N=32,n=N*N;int repeat=argc>1?atoi(argv[1]):100;std::vector<std::vector<Z>>a(3,std::vector<Z>(n)),gold;for(int y=0;y<N;y++)for(int x=0;x<N;x++){if(abs(x-N/2)>=8&&abs(x-N/2)<=10&&abs(y-N/2)<=4)a[0][y*N+x]=1;a[2][y*N+x]=Z(((7*x+3*y)%23-11)/32.,((5*x+8*y)%19-9)/64.);}a[1][2*N+1]=1;std::vector<double>prefix;for(auto&v:a){gold.push_back(dft(v,N));for(Z z:v){prefix.push_back(z.real());prefix.push_back(z.imag());}}int version=0;cufftGetVersion(&version);Dl_info info;dladdr(dlsym(RTLD_DEFAULT,"cufftGetVersion"),&info);printf("STUDY_VENDOR {\"version_integer\":%d,\"library\":\"%s\",\"plan_API\":\"cufftPlan2d_Z2Z\",\"stream\":0}\n",version,info.dli_fname);
std::vector<cufftHandle>plans(3);std::vector<cufftDoubleComplex*>ds(3);std::vector<std::vector<cufftDoubleComplex>>host(3,std::vector<cufftDoubleComplex>(n));for(int f=0;f<3;f++){for(int i=0;i<n;i++)host[f][i]=make_cuDoubleComplex(a[f][i].real(),a[f][i].imag());if(cufftPlan2d(&plans[f],N,N,CUFFT_Z2Z)!=CUFFT_SUCCESS)return 4;cudaMalloc(&ds[f],n*sizeof(cufftDoubleComplex));cudaMemcpy(ds[f],host[f].data(),n*sizeof(cufftDoubleComplex),cudaMemcpyHostToDevice);if(cufftExecZ2Z(plans[f],ds[f],ds[f],CUFFT_FORWARD)!=CUFFT_SUCCESS)return 5;cudaDeviceSynchronize();}
for(int trial=1;trial<=5;trial++){double elapsed=0;for(int f=0;f<3;f++)for(int rep=0;rep<repeat;rep++){cudaMemcpy(ds[f],host[f].data(),n*sizeof(cufftDoubleComplex),cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();if(cufftExecZ2Z(plans[f],ds[f],ds[f],CUFFT_FORWARD)!=CUFFT_SUCCESS)return 6;cudaDeviceSynchronize();elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/repeat;}std::vector<double>vals;double err=0;bool ok=cudaGetLastError()==cudaSuccess;for(int f=0;f<3;f++){std::vector<cufftDoubleComplex>got(n);cudaMemcpy(got.data(),ds[f],n*sizeof(cufftDoubleComplex),cudaMemcpyDeviceToHost);double energy=0,inputenergy=0;Z dc=0;for(int i=0;i<n;i++){Z z(got[i].x,got[i].y);double intensity=std::norm(z);err=std::max({err,fabs(z.real()-gold[f][i].real()),fabs(z.imag()-gold[f][i].imag()),fabs(intensity-std::norm(gold[f][i]))});ok&=std::isfinite(intensity);energy+=intensity;inputenergy+=std::norm(a[f][i]);dc+=a[f][i];vals.push_back(z.real());vals.push_back(z.imag());if(f==1){int x=i%N,y=i/N;ok&=abs(z-std::polar(1.0,-2*M_PI*(x+2*y)/N))<1e-10;}}for(auto z:got)vals.push_back(z.x*z.x+z.y*z.y);ok&=fabs(energy-N*N*inputenergy)<1e-8&&abs(Z(got[0].x,got[0].y)-dc)<1e-10;}ok&=err<1e-8;auto art=prefix;art.insert(art.end(),vals.begin(),vals.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"sum_three_inplace_cufft_Z2Z_forward_exec_device_sync_only\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",vals.size(),err,repeat,path.c_str(),art.size());if(!ok)return 2;}for(int f=0;f<3;f++){cufftDestroy(plans[f]);cudaFree(ds[f]);}}
